  /** Filter by user ID */
  userId?: string;

  /** Filter by tenant ID */
  tenantId?: string;

  /** Filter by memory space ID */
  memorySpaceId?: string;

  /** Filter by session status */
  status?: SessionStatus;

  /** Maximum results to return */
  limit?: number;

  /** Offset for pagination */
  offset?: number;
}

