 */
export interface A2AConversationMessage {
  /** Sender agent ID */
  from: string;
  /** Receiver agent ID */
  to: string;
  /** Message content */
  message: string;
  /** Importance level */
  importance: number;
  /** Timestamp */
  timestamp: number;
  /** Message ID */
  messageId: string;
  /** Vector memory ID */
  memoryId: string;
  /** ACID message ID (if tracked) */
  acidMessageId?: string;
  /** Tags */
  tags?: string[];
}

/**
 * A2A timeout error
 */
export class A2ATimeoutError extends Error {
  public readonly name = "A2ATimeoutError";

  constructor(
    message: string,
    public readonly messageId: string,
    public readonly timeout: number,
  ) {
    super(message);
  }
}

