    conversationId: v.optional(v.string()),
    messageId: v.optional(v.string()),
    memoryId: v.optional(v.string()),
    artifactId: v.optional(v.string()),
    userId: v.optional(v.string()),
    type: v.optional(attachmentTypeValidator),

