            q
              .eq("memorySpaceId", args.memorySpaceId!)
              .lt("timestamp", args.olderThan),
          )
          .collect()
      : await ctx.db
          .query("factHistory")
          .withIndex("by_timestamp", (q) => q.lt("timestamp", args.olderThan))
