      authority: row.authority, triggeredBy: authority.principalId, enforcementType: "manual", layers: args.options?.layers ?? [],
      rules: args.options?.rules ?? [], versionsDeleted: 0, recordsPurged: 0, storageFreed: 0, executedAt: now });
