export const derivedVector = v.object({
  ...sourceReference, vectorId: v.string(), chunkId: v.string(), tenantId: v.string(),
  memorySpaceId: v.string(), profile: embeddingProfile, embedding: v.array(v.float64()),
  processingReceiptId: v.string(),
});
export const processingIdentity = v.object({
  ...sourceReference, stage: v.union(v.literal("extract"), v.literal("facts"), v.literal("vectors")),
  semanticPolicyVersion: v.string(),
});
const factType = v.union(v.literal("preference"), v.literal("identity"), v.literal("knowledge"),
  v.literal("relationship"), v.literal("event"), v.literal("observation"), v.literal("custom"));
export const derivedFact = v.object({
  _id: v.string(), factId: v.string(), tenantId: v.optional(v.string()), memorySpaceId: v.string(),
  ownerPrincipalId: v.string(), lineage: sourceLineage, extractionPolicyVersion: v.string(),
  fact: v.string(), factType, subject: v.optional(v.string()), predicate: v.optional(v.string()),
  object: v.optional(v.string()), confidence: v.number(),
  sourceType: v.union(v.literal("conversation"), v.literal("system"), v.literal("tool"), v.literal("manual"), v.literal("a2a")),
  tags: v.array(v.string()), version: v.number(), createdAt: v.number(), updatedAt: v.number(),
  validFrom: v.optional(v.number()), validUntil: v.optional(v.number()),
  supersededBy: v.optional(v.string()), supersedes: v.optional(v.string()),
  userId: v.optional(v.string()), participantId: v.optional(v.string()),
  entities: v.optional(v.array(v.object({ name: v.string(), type: v.string(), fullValue: v.optional(v.string()) }))),
  relations: v.optional(v.array(v.object({ subject: v.string(), predicate: v.string(), object: v.string() }))),
});
export const commitDerivedInput = v.object({
  source: v.object(sourceReference), identity: processingIdentity,
  chunks: v.optional(v.array(sourceChunk)), vectors: v.optional(v.array(derivedVector)),
  facts: v.optional(v.array(derivedFact)), expectedFactVersions: v.optional(v.record(v.string(), v.number())),
});

export const runtimeMemoryTables = {
  runtimeMemorySources: defineTable(sourceContent.fields)
    .index("by_scope_source", ["tenantId", "memorySpaceId", "lineage.sourceId"])
    .index("by_scope_event", ["tenantId", "memorySpaceId", "lineage.sourceEventId"]),
  runtimeMemoryChunks: defineTable(sourceChunk.fields)
    .index("by_scope_chunk", ["tenantId", "memorySpaceId", "chunkId"]),
  runtimeMemoryVectors: defineTable({ ...derivedVector.fields, profileId: v.string(), scopeProfileKey: v.string(),
    ownerPrincipalId: v.string(), scopeProfileOwnerKey: v.string() })
    .index("by_scope_vector", ["tenantId", "memorySpaceId", "vectorId"])
    .index("by_scope_source_revision", ["tenantId", "memorySpaceId", "sourceId", "sourceRevision"])
    .vectorIndex("by_default_embedding_v1", { vectorField: "embedding", dimensions: 1536,
      filterFields: ["tenantId", "memorySpaceId", "profileId", "scopeProfileKey", "scopeProfileOwnerKey"] }),
  runtimeMemoryReceipts: defineTable({
    tenantId: v.string(), memorySpaceId: v.string(), receiptId: v.string(),
    identity: processingIdentity, canonicalIdentity: v.string(), canonicalPayload: v.string(), createdAt: v.number(),
  }).index("by_scope_receipt", ["tenantId", "memorySpaceId", "receiptId"]),
};

/** Modern memory operations share pure domain logic and required backend adapters. */
import type { MemoryDomainAdapters, SourceLineage, TrustedMemoryScope, DerivedFact } from "./_cortex/shared/domain/contracts";
import { DEFAULT_EMBEDDING_PROFILE, normalizeSourceText, semanticHash } from "./_cortex/shared/domain/profile";
import { SOURCE_EXTRACTION_POLICY_VERSION, extractSourceFacts, prepareSourceContent, processingIdentityKey, validateModelEmbeddings } from "./_cortex/shared/domain/sources";
import { deduplicateResults, factToRecallItem, formatForLLM, rankResults } from "./_cortex/shared/domain/recall";
import type { RecallItem } from "./_cortex/shared/types/index";
import { canonicalMemoryValue, memoryError } from "./runtimeMemoryRepository";

export function assertMemoryRequestId(requestId: string): void {
  if (!requestId.trim() || requestId.length > 128) memoryError("INVALID_INPUT", "A nonempty request ID of at most 128 characters is required");
}
/** Exact tuple, rather than a digest, retains canonical admission identity on collision. */
export function explicitSourceLineage(scope: TrustedMemoryScope, requestId: string): SourceLineage {
  assertMemoryRequestId(requestId);
  const sourceId = `explicit:${JSON.stringify([scope.tenantId, scope.memorySpaceId, scope.principalId, requestId])}`;
  return { sourceId, sourceEventId: sourceId, sourceRevision: 1, role: "user", trust: "user_assertion" };
}

/** No provider credentials/fallback. Task04 installs the governed Gateway adapter here. */
export function unconfiguredMemoryModel(): MemoryDomainAdapters["model"] {
  const unavailable = () => memoryError("POLICY_NOT_CONFIGURED", "Governed backend memory model policy is not configured");
  return { extract: async () => unavailable(), resolve: async () => unavailable(), embed: async () => unavailable() };
}

export async function rememberMemory(
  adapters: MemoryDomainAdapters, input: { text: string; lineage: SourceLineage },
): Promise<{ sourceId: string; sourceRevision: number; receiptId: string; created: boolean; facts: Omit<DerivedFact, "_id">[] }> {
  const { repository, model, clock } = adapters;
  await repository.recheckAuthority();
  const prepared = await prepareSourceContent(repository.scope, input.lineage, input.text, clock);
  const persisted = await repository.putSource(prepared.source);
  const source = persisted.source;
  const reference = { sourceId: source.lineage.sourceId, sourceEventId: source.lineage.sourceEventId, sourceRevision: source.lineage.sourceRevision };
  const identity = { ...reference, stage: "facts" as const,
    semanticPolicyVersion: `${SOURCE_EXTRACTION_POLICY_VERSION}+${DEFAULT_EMBEDDING_PROFILE.profileId}` };
  const receiptId = await processingIdentityKey(identity);
  const recheckSource = async () => {
    await repository.recheckAuthority();
    const current = await repository.getSource(source.lineage.sourceId);
    if (!current || canonicalMemoryValue(current) !== canonicalMemoryValue(source)) memoryError("STALE_SOURCE", "Source changed before model dispatch or commit");
  };
  // Rechecks immediately precede each internal dispatch; an injected model never grants access.
  await recheckSource();
  const extracted = source.lineage.role === "assistant" ? [] : await extractSourceFacts(source, model, {
    operationId: `memory.extract:${receiptId}`, policyVersion: SOURCE_EXTRACTION_POLICY_VERSION, attempt: 1, source: reference,
  });
  await recheckSource();
  const embeddingResult = await model.embed({ purpose: "embedding.memory", operationId: `embedding.memory:${receiptId}`,
    policyVersion: DEFAULT_EMBEDDING_PROFILE.profileId, attempt: 1, source: reference,
    profile: DEFAULT_EMBEDDING_PROFILE, texts: prepared.chunks.map((chunk) => chunk.text) });
  validateModelEmbeddings(embeddingResult, DEFAULT_EMBEDDING_PROFILE, prepared.chunks.length);
  if (extracted.length > 100) memoryError("INVALID_INPUT", "Extraction exceeds the bounded fact commit size");
  const facts: DerivedFact[] = await Promise.all(extracted.map(async (fact, ordinal) => ({
    _id: "", factId: await semanticHash(JSON.stringify([source.tenantId, source.memorySpaceId, source.lineage,
      SOURCE_EXTRACTION_POLICY_VERSION, ordinal, fact.fact])),
    tenantId: source.tenantId, memorySpaceId: source.memorySpaceId, ownerPrincipalId: source.ownerPrincipalId,
    fact: fact.fact, factType: fact.factType, subject: fact.subject, predicate: fact.predicate, object: fact.object,
    confidence: fact.confidence * 100, tags: fact.tags ?? [], entities: fact.entities, relations: fact.relations,
    sourceType: source.lineage.role === "tool" ? "tool" as const : "manual" as const,
    lineage: fact.lineage, extractionPolicyVersion: SOURCE_EXTRACTION_POLICY_VERSION,
    version: 1, createdAt: source.createdAt, updatedAt: source.createdAt,
  })));
  const vectors = await Promise.all(prepared.chunks.map(async (chunk, index) => ({
    sourceId: chunk.sourceId, sourceEventId: chunk.sourceEventId, sourceRevision: chunk.sourceRevision,
    vectorId: await semanticHash(JSON.stringify([chunk.chunkId, DEFAULT_EMBEDDING_PROFILE, receiptId])), chunkId: chunk.chunkId,
    tenantId: source.tenantId, memorySpaceId: source.memorySpaceId, profile: DEFAULT_EMBEDDING_PROFILE,
    embedding: embeddingResult.vectors[index]!, processingReceiptId: receiptId,
  })));
  await recheckSource();
  const committed = await repository.commitDerived({ source: reference, identity, chunks: prepared.chunks, vectors, facts,
    expectedFactVersions: Object.fromEntries(facts.map((fact) => [fact.factId, 0])) });
  // A write receipt returns only this committed payload by stable factId, without unrelated read access.
  const committedFacts = facts.map(({ _id: _id, ...fact }) => fact);
  return { sourceId: source.lineage.sourceId, sourceRevision: source.lineage.sourceRevision,
    receiptId: committed.receiptId, created: committed.created, facts: committedFacts };
}

export async function recallMemory(
  adapters: MemoryDomainAdapters, input: { text: string; requestId: string; limit: number },
): Promise<{ items: RecallItem[]; context: string; profileId: string }> {
  assertMemoryRequestId(input.requestId);
  if (!Number.isSafeInteger(input.limit) || input.limit < 1 || input.limit > 100) memoryError("INVALID_INPUT", "Limit must be between 1 and 100");
  const { repository, model, clock } = adapters;
  const text = normalizeSourceText(input.text);
  await repository.recheckAuthority();
  // Read methods enforce read independently; a write-only injected adapter cannot dispatch recall.
  await repository.listFacts({ limit: 1 });
  const operationId = `embedding.query:${JSON.stringify([repository.scope.tenantId, repository.scope.memorySpaceId,
    repository.scope.principalId, input.requestId, DEFAULT_EMBEDDING_PROFILE.profileId])}`;
  const result = await model.embed({ purpose: "embedding.query", operationId,
    policyVersion: DEFAULT_EMBEDDING_PROFILE.profileId, attempt: 1, profile: DEFAULT_EMBEDDING_PROFILE, texts: [text] });
  validateModelEmbeddings(result, DEFAULT_EMBEDDING_PROFILE, 1);
  const vectors = await repository.searchVectors({ text, profile: DEFAULT_EMBEDDING_PROFILE, embedding: result.vectors[0]! }, input.limit);
  const facts = await repository.listFacts({ limit: input.limit });
  const vectorItems: RecallItem[] = vectors.map((match) => ({ type: "memory", id: match.chunk.chunkId,
    content: match.chunk.text, score: match.score, source: "vector", memory: {
      _id: match.vector.vectorId, memoryId: match.chunk.chunkId, tenantId: match.source.tenantId,
      memorySpaceId: match.source.memorySpaceId, userId: match.source.ownerPrincipalId, content: match.chunk.text,
      contentType: "raw", sourceType: match.source.lineage.role === "tool" ? "tool" : "conversation",
      sourceTimestamp: match.source.createdAt, messageRole: match.source.lineage.role === "user" ? "user" : "agent",
      importance: 50, tags: [], version: match.source.lineage.sourceRevision, previousVersions: [],
      createdAt: match.source.createdAt, updatedAt: match.source.createdAt, accessCount: 0,
    }, graphContext: { connectedEntities: [] } }));
  await repository.recheckAuthority();
  const items = rankResults(deduplicateResults([...vectorItems, ...facts.map((fact) => factToRecallItem(fact, "facts", 0.7))]), clock).slice(0, input.limit);
  return { items, context: formatForLLM(items, clock), profileId: DEFAULT_EMBEDDING_PROFILE.profileId };
}

/** Verified generic metadata authority; deliberately independent of memory/fact adapters. */
import { ConvexError, v } from "convex/values";
import type { MutationCtx, QueryCtx } from "./_generated/server";
import type { Doc } from "./_generated/dataModel";
import type { RuntimeAuthority, RuntimeAuthorityReference, RuntimeCapability, RuntimeResource } from "./_cortex/shared/auth/verified";
import { createAuthorityReader, requireAuthority, recheckAuthority } from "./runtimeAuth";

export const scopeArgs = { tenantId: v.optional(v.string()), memorySpaceId: v.optional(v.string()) };
export interface ScopeSelectors { tenantId?: string; memorySpaceId?: string }
export type MetadataTable = "immutable" | "mutable" | "sessions";
export type MetadataRow = Doc<"immutable"> | Doc<"mutable"> | Doc<"sessions">;
type ReadCtx = Pick<QueryCtx, "db" | "auth">;
export function denied(): never { throw new ConvexError({ code: "FORBIDDEN", message: "Access denied" }); }
export function invalid(): never { throw new ConvexError({ code: "INVALID_INPUT", message: "Invalid metadata input" }); }
export function nonempty(...values: string[]): void { if (values.some((value) => !value.trim())) invalid(); }
export function page(value: number | undefined, fallback: number): number {
  const result = value ?? fallback;
  if (!Number.isSafeInteger(result) || result < 0) invalid();
  return result;
}
/** Frozen v1 linked-source key: JSON array encoding is unambiguous for arbitrary strings. */
export function sourceId(table: MetadataTable, first: string, second?: string): string {
  return `${table === "sessions" ? "session" : table}:${JSON.stringify(second === undefined ? [first] : [first, second])}`;
}
export function resource(table: MetadataTable, row: MetadataRow): RuntimeResource {
  if (!row.tenantId || !row.ownerPrincipalId) denied();
  const id = "type" in row ? sourceId(table, row.type, row.id)
    : "namespace" in row ? sourceId(table, row.namespace, row.key) : sourceId(table, row.sessionId);
  return { resourceType: "source", resourceId: id, tenantId: row.tenantId,
    memorySpaceId: row.memorySpaceId, ownerPrincipalId: row.ownerPrincipalId };
}
export async function authority(ctx: ReadCtx, capability: RuntimeCapability, selectors: ScopeSelectors): Promise<RuntimeAuthority> {
  return await requireAuthority(ctx, { capability, tenantId: selectors.tenantId, memorySpaceId: selectors.memorySpaceId });
}
export function actor(authority: RuntimeAuthority, userId?: string): void {
  if (userId !== undefined && userId !== authority.userId) denied();
}
function profileEligible(authority: Pick<RuntimeAuthority, "resourceAccess" | "userId">, type: string, id: string): boolean {
  return type !== "user" || authority.resourceAccess !== "own" || id === authority.userId;
}
export function profile(authority: RuntimeAuthority, type: string, id: string): void {
  if (!profileEligible(authority, type, id)) denied();
}
export async function check(ctx: Pick<QueryCtx, "db">, table: MetadataTable, row: MetadataRow,
  auth: RuntimeAuthority, capability: RuntimeCapability): Promise<RuntimeAuthority> {
  if (row.tombstonedAt !== undefined) denied();
  if ("type" in row) profile(auth, row.type, row.id);
  await finalChecks(ctx, [{ auth, capability, resource: resource(table, row) }]);
  return auth;
}
function deadline(grant: { expiresAt?: number } | null): void {
  if (!grant || (grant.expiresAt !== undefined && (!Number.isFinite(grant.expiresAt) || Date.now() >= grant.expiresAt))) denied();
}
/** Transaction snapshot control checks plus synchronous lifetime check after the final await. */
export async function finalChecks(ctx: Pick<QueryCtx, "db">, checks: Array<{ auth: RuntimeAuthorityReference; capability: RuntimeCapability; resource?: RuntimeResource }>): Promise<void> {
  const grants = await Promise.all(checks.map(({ auth }) => createAuthorityReader(ctx).getGrant(auth.grantId)));
  for (const { auth, capability, resource: target } of checks) await recheckAuthority(ctx, auth,
    target ? { capability, resource: target } : { capability, tenantId: auth.tenantId, memorySpaceId: auth.memorySpaceId });
  for (const grant of grants) deadline(grant);
}
export async function fresh(ctx: Pick<QueryCtx, "db">, auth: RuntimeAuthority, capability: RuntimeCapability): Promise<void> {
  await finalChecks(ctx, [{ auth, capability }]);
}
export function canonicalFields(auth: RuntimeAuthority) {
  return { tenantId: auth.tenantId, memorySpaceId: auth.memorySpaceId, ownerPrincipalId: auth.principalId, userId: auth.userId };
}
export async function newResource(ctx: Pick<QueryCtx, "db">, auth: RuntimeAuthority, id: string): Promise<void> {
  await recheckAuthority(ctx, auth, { capability: "write", resource: { resourceType: "source", resourceId: id,
    tenantId: auth.tenantId, memorySpaceId: auth.memorySpaceId, ownerPrincipalId: auth.principalId } });
}
/** Existence-only canonical-key preflight, including foreign/missing-owner duplicates. */
async function uniqueKey(ctx: Pick<QueryCtx, "db">, table: MetadataTable, row: MetadataRow): Promise<void> {
  let conflict: MetadataRow | null;
  if (table === "immutable" && "type" in row) conflict = await ctx.db.query("immutable").withIndex("by_runtime_key", (q) =>
    q.eq("tenantId", row.tenantId).eq("memorySpaceId", row.memorySpaceId).eq("type", row.type).eq("id", row.id))
    .filter((q) => q.neq(q.field("_id"), row._id)).first();
  else if (table === "mutable" && "namespace" in row) conflict = await ctx.db.query("mutable").withIndex("by_runtime_key", (q) =>
    q.eq("tenantId", row.tenantId).eq("memorySpaceId", row.memorySpaceId).eq("namespace", row.namespace).eq("key", row.key))
    .filter((q) => q.neq(q.field("_id"), row._id)).first();
  else if (table === "sessions" && "sessionId" in row) conflict = await ctx.db.query("sessions").withIndex("by_runtime_key", (q) =>
    q.eq("tenantId", row.tenantId).eq("memorySpaceId", row.memorySpaceId).eq("sessionId", row.sessionId))
    .filter((q) => q.neq(q.field("_id"), row._id)).first();
  else denied();
  if (conflict) denied();
